var n=`0116-kiluvoileib`;var t=`world-0116`;var r=`EE`;var o=`northern-europe`;var s=4;var a=30;var u={en:`Kiluvõileib`,ua:`Бутерброд із кількою`};var l={en:`A classic dish from Estonia, featuring rye bread, sprat, chicken egg, cucumber. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Естонія. Основні складники: житній хліб, кілька, куряче яйце, огірок. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Toast these ingredients over medium heat for about 5 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 5 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:5,i:[[`rye-bread`,240,`g`],[`unsalted-butter`,30,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 8 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 8 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:8,i:[[`sprat`,160,`g`],[`sunflower-oil`,15,`ml`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,2,`pcs`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:5,i:[[`cucumber`,120,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`dill`,15,`g`],[`lemon-juice`,15,`ml`]]}];var g={slug:n,id:t,country:`EE`,region:o,servings:4,minutes:30,title:u,text:l,steps:d};export{r as country,g as default,t as id,a as minutes,o as region,s as servings,n as slug,d as steps,l as text,u as title};